sp_widget.client_script:
api.controller = function() {
  /* widget controller */
  var c = this;

  c.getAttachment = function() {
    var root = document.querySelectorAll('.sp-page-root');

    c.server.get({
      parameter1: root[0].innerHTML, 
      action: "getAttachment"
    }).then(function(response) {
      var a = document.createElement('a');

      a.href = window.location.origin + 
               "/sys_attachment.do?sys_id=" + 
               response.data.sys_id; 
      a.download = response.data.sys_id;
      a.style.display = 'none';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    });
  };
};

sp_widget.script:
(function() {
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */

    if (input && input.action == "getAttachment") {
        gs.info("Received Parameter: " + input.parameter1);

        var v = new sn_pdfgeneratorutils.PDFGenerationAPI();
        var html = input.parameter1;  
        var number = "0c5f3cece1b12010f877971dea0b1449";
        var guid = gs.generateGUID();

        // 调用PDF转换API
        var result = v.convertToPDF(html, "incident", number, guid);
        var sys_id = result.attachment_id;

        // 设置响应数据
        data.sys_id = sys_id;
        data.filename = guid;  // 使用生成的GUID作为文件名
    }
})();
